// policy/adapters/file-size.mjs: files over 600 lines as sites, one script for every language (contracts §12:528;
// ADR 0028:18; 2.1-Q214, 2.1-Q243; oxlint's max-lines is denied, so this is the one check of file size).
//
// Over the paths it is given, each source file (SOURCE: ts, tsx, js, mjs, cjs, rs, py, sh, css), tests included, is
// counted the same way, by its newline-terminated lines (a last line without a newline is not one), and a file over
// LIMIT lines is one site { rule: 'file-size', path, line } at its path, `line` its count. Exempt, never a site:
//   - a generated file: its first line is a comment saying `Generated by` (any case), the header every generator in
//     the repository writes (bindings-gen, gen:types, policy/generate.mjs, species_catalog_contract.py);
//   - a data fixture: a file under a `__fixtures__/` or `__tests__/fixtures/` directory.
// A path given that cannot be read is tool-failed, never a file under the limit.
import fs from 'node:fs';
import path from 'node:path';

export const LIMIT = 600;
const SOURCE = /\.(?:ts|tsx|js|mjs|cjs|rs|py|sh|css)$/u;
const GENERATED = /^\s*(?:\/\/+|#+|\/\*+)\s*generated by\b/iu;
const DATA_FIXTURE = /(?:^|\/)(?:__fixtures__|__tests__\/fixtures)\//u;

const fail = (message) => { throw Object.assign(new Error(`file-size: ${message}`), { code: 'tool-failed' }); };

export function collect({ root, paths }) {
  const sites = [];
  for (const p of paths) {
    if (!SOURCE.test(p) || DATA_FIXTURE.test(p)) continue;
    let text;
    try {
      text = fs.readFileSync(path.join(root, p), 'utf8');
    } catch (error) {
      fail(`cannot read ${p}: ${error.code ?? error.message}`);
    }
    if (GENERATED.test(text.slice(0, text.indexOf('\n') + 1 || undefined))) continue;
    let lines = 0;
    for (let at = text.indexOf('\n'); at !== -1; at = text.indexOf('\n', at + 1)) lines++;
    if (lines > LIMIT) sites.push({ rule: 'file-size', path: p, line: lines });
  }
  return sites;
}
